<?php $__env->startSection('title','Order Details'); ?>
<?php $__env->startSection('content'); ?>
<section class="order-detail-head"><div><span>Order ID <b>#<?php echo e($order->order_number); ?></b></span><p>Placed on <strong><?php echo e($order->created_at->format('d M, Y h:i A')); ?></strong><i></i> Est. delivery <strong>3–4 days</strong></p></div><span class="customer-status"><?php echo e($order->status); ?></span></section>
<div class="order-detail-grid"><section class="customer-card order-products"><div class="order-store"><span><i class="bi bi-shop"></i></span><div><small>Purchased from</small><b><?php echo e($order->warehouse?->name ?: 'EBay Store'); ?></b><em><i class="bi bi-star-fill"></i> 4.8</em></div></div><div class="order-products-heading">Products (<?php echo e($order->items->count()); ?>)</div><?php $__currentLoopData = $order->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article class="order-product-item"><?php if($item->product?->thumbnail): ?><img src="<?php echo e($item->product->thumbnail->url); ?>" alt="<?php echo e($item->product_name); ?>"><?php else: ?><div><i class="bi bi-image"></i></div><?php endif; ?><div><b><?php echo e($item->product_name); ?></b><small><?php echo e($item->product?->brand?->name); ?></small></div><span><?php echo e(rtrim(rtrim(number_format($item->quantity,2),'0'),'.')); ?> × $<?php echo e(number_format($item->unit_price,2)); ?></span></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></section><aside class="customer-card order-summary"><div class="d-flex justify-content-between border-bottom pb-3 mb-2"><b>Order Id</b><span>#<?php echo e($order->order_number); ?></span></div><h2>Order Summary</h2><div><span>Items</span><b><?php echo e(rtrim(rtrim(number_format($order->items->sum('quantity'),2),'0'),'.')); ?></b></div><div><span>Subtotal</span><b>$<?php echo e(number_format($order->subtotal,2)); ?></b></div><?php if($order->discount > 0): ?><div class="discount"><span>Discount</span><b>−$<?php echo e(number_format($order->discount,2)); ?></b></div><?php endif; ?><div><span>Shipping Charge</span><b>$<?php echo e(number_format($order->shipping_charge,2)); ?></b></div><hr><div class="order-total"><span>Total Amount</span><b>$<?php echo e(number_format($order->total,2)); ?></b></div><section class="payment-method"><small>Payment Method</small><b><?php echo e($order->payment_method); ?></b><span><?php echo e(ucfirst($order->payment_status)); ?></span></section><a class="customer-action" href="<?php echo e(route('customer.orders')); ?>"><i class="bi bi-arrow-left"></i> Back to orders</a></aside></div>
